import { ChatMessage } from "../models/message.model.js";
import { asyncHandler } from "../utils/AsyncHandler.js";
import { ApiError } from "../utils/ApiError.js";
import { ApiResponse } from "../utils/ApiResponse.js";
import { emitSocketEvent } from "../utils/socket/index.js";
import { ChatEventEnum } from "../constants.js";

/**
 * @method sendMessage
 * Handles the final step of the AI-powered "Mood" chat.
 * 1. Receives the user's mood query (receiverMessage).
 * 2. Accesses 'req.chatResponse' (the AI's text reason) and 'req.suggestedSongsIds' 
 *  generated by the 'getSuggestedSong' middleware.
 * 3. Creates a new ChatMessage record containing both the user's message and the AI's response.
 * 4. Persists the array of recommended song ObjectIds in the 'recommendedSongs' field.
 * 5. Emits a socket event so the UI updates in real-time without a refresh.
 */
const sendMessage = asyncHandler(async (req, res) => {
  // Step 1: Extract the user message from the request body
  // Step 2: Pass the req.chatResponse and req.suggestedSongsIds to the ChatMessage model to save the message
  // Step 3: If the message is saved successfully, return a success response with the message

  // extrecting the user message from the request body
  const { receiverMessage } = req.body;
  //console.log("receiverMessage", receiverMessage);

  // checking if the receiverMessage and content is present in the request body
  if (!receiverMessage) {
    throw new ApiError(400, "Receiver message are required");
  }

  // checking if the req.chatResponse is present in the request body
  const chatResponse = req.chatResponse;

  if (!req.chatResponse) {
    throw new ApiError(400, "Chat response is required");
  }
  //console.log("chatResponse", chatResponse);

  // checking if the req.suggestedSongsIds is present in the request body
  const suggestedSongsIds = req.suggestedSongsIds;

  if (!req.suggestedSongsIds) {
    throw new ApiError(400, "Suggested Song Ids are required");
  }
  //console.log("suggestedSongsIds: ", suggestedSongsIds);

  // passing the req.chatResponse and req.suggestedSongsIds to the ChatMessage model to save the message
  // creating a new message object with the sender and receiver id
  const message = await ChatMessage.create({
    receiverId: req.user._id.toHexString(),
    receiverMessage: receiverMessage,
    receiverLastMessage: receiverMessage,
    senderMessage: chatResponse,
    senderLastMessage: chatResponse,
    recommendedSongs: suggestedSongsIds,
    messageType: "recommendation",
  });

  if (!message) {
    throw new ApiError(400, "Unable to send message");
  }

  // emitting the socket event to the user with the message id
  emitSocketEvent(
    req,
    req.user._id,
    ChatEventEnum.MESSAGE_RECEIVED_EVENT,
    message,
  );

  return res
    .status(200)
    .json(new ApiResponse(200, message, "Message sent successfully"));
});

/**
 * @method recommendSongMessage
 * Finalizes the "Next Song" recommendation flow.
 * 1. Retrieves the 'suggestedSongs' (full song objects) from the 'playNextRecommendedSong' middleware.
 * 2. Unlike the mood chat, this typically returns just the list of songs to populate 
 * an "Up Next" or "Related Tracks" UI component.
 * 3. Uses Socket.io to push these recommendations to the specific authenticated user.
 */
const recommendSongMessage = asyncHandler(async (req, res) => {
  // Step 1: Extract the suggested songs from the request body
  // Step 3: Return a success response with the message

  // checking if the req.suggestedSongs is present in the request body
  const suggestedSongs = req.suggestedSongs;

  if (!req.suggestedSongs) {
    throw new ApiError(400, "suggestedSongs is required");
  }
  //console.log("Suggested Songs: ", suggestedSongs);

  // emitting the socket event to the user with the message id
  emitSocketEvent(
    req,
    req.user._id,
    ChatEventEnum.MESSAGE_RECEIVED_EVENT,
    suggestedSongs,
  );

  return res
    .status(200)
    .json(new ApiResponse(200, suggestedSongs, "Message sent successfully"));
});

/**
 * @method getAllMessages
 * Data Retrieval Logic for Chat History.
 * 1. Queries the ChatMessage model for all entries belonging to the authenticated user.
 * 2. Uses '.select("-recommendedSongs")' to optimize the query, as the full song details 
 * are usually only needed when opening a specific message bubble.
 */
const getAllMessages = asyncHandler(async (req, res) => {
  // Step 1: Get all the messages from the ChatMessage model
  // Step 2: If the messages are found, return a success response with the messages

  const messages = await ChatMessage.find({
    receiverId: req.user._id.toHexString(),
  }).select("-receiverId -recommendedSongs");
  //console.log("messages", messages);

  if (!messages) {
    throw new ApiError(400, "Unable to find messages");
  }

  return res
    .status(200)
    .json(new ApiResponse(200, messages, "Messages retrieved successfully"));
});

/**
 * @method getMessage
 * Retrieves a single specific chat interaction by its unique Database ID.
 * Useful to get the chat message.
 */
const getMessage = asyncHandler(async (req, res) => {
  // Step 1: Get the message id from the request params
  // Step 2: Get the message from the ChatMessage model
  // Step 3: If the messages are found, return a success response with the messages

  const { messageId } = req.params;

  if (!messageId) {
    throw new ApiError(400, "Message id is required");
  }

  const messages = await ChatMessage.findOne({
    _id: messageId,
  }).select("-receiverId -recommendedSongs");
  //console.log("messages", messages);

  if (!messages) {
    throw new ApiError(400, "Unable to find messages");
  }

  return res
    .status(200)
    .json(new ApiResponse(200, messages, "Message retrieved successfully"));
});

/**
 * @method getLastMessage
 * Specialized query to find the most recent interaction.
 * Often used on the frontend "Home" or "Library" screen to show the user 
 * their most recent AI-generated playlist.
 */
const getLastMessage = asyncHandler(async (req, res) => {
  // Step 2: Get the message from the ChatMessage model
  // Step 3: If the messages are found, return a success response with the messages

  const lastMessage = await ChatMessage.findOne({
    receiverId: req.user._id.toHexString(),
  })
    .sort({ createdAt: -1 })
    .select("recommendedSongs");

  if (!lastMessage) {
    throw new ApiError(400, "Unable to find last message");
  }

  return res
    .status(200)
    .json(
      new ApiResponse(200, lastMessage, "Last Message retrieved successfully"),
    );
});

/**
 * @method deleteReceiverMessage
 * Handles message "Soft Deletion".
 * Instead of removing the entire database row, this methods set specific fields 
 * (like 'receiverMessage') to 'undefined'.
 * This allows the system to maintain the record for analytics or 
 * recommendation history while hiding the text from the user's UI.
 */
const deleteReceiverMessage = asyncHandler(async (req, res) => {
  // Step 1: Get the message id from the request params
  // Step 2: Find the message by id and delete it
  // Step 3: If the message is deleted successfully, return a success response

  const { messageId } = req.params;
  // console.log("messageId: ", messageId);

  if (!messageId) {
    throw new ApiError(400, "Message id is required");
  }

  const message = await ChatMessage.findById(messageId);
  message.receiverMessage = undefined;
  message.save();
  // console.log("message: ", message);

  if (!message) {
    throw new ApiError(400, "Unable to delete message");
  }

  // emitting the socket event to the user with the message id
  emitSocketEvent(
    req,
    req.user._id,
    ChatEventEnum.MESSAGE_DELETE_EVENT,
    message,
  );

  return res
    .status(200)
    .json(
      new ApiResponse(200, undefined, "Receiver Message deleted successfully"),
    );
});

